// With site data blocked (a browser set to block all cookies and site data),
// reading `localStorage` throws a SecurityError. The Supabase client reads it
// while its module loads (client.ts, previewAuthStorage.ts), so the app never
// drew. Both of those files are regenerated by Lovable, which undid a fix made
// inside them (QA 22 Nov 2026, P10-03; undone by Lovable on 23 Nov), so the
// guard lives here and runs first: when `localStorage` cannot be read, the
// page gets a storage that lasts for the tab, and the session is kept for it.

/** A Storage kept in memory for the page. */
export function memoryStorage(): Storage {
  const items = new Map<string, string>();
  return {
    get length() { return items.size; },
    clear: () => items.clear(),
    getItem: (key: string) => (items.has(key) ? items.get(key)! : null),
    key: (index: number) => Array.from(items.keys())[index] ?? null,
    removeItem: (key: string) => { items.delete(key); },
    setItem: (key: string, value: string) => { items.set(key, String(value)); },
  };
}

/** Puts a page-lived storage in place of `localStorage` when the browser refuses it. Answers whether it did. */
export function guardLocalStorage(target: typeof globalThis = globalThis): boolean {
  try {
    const storage = target.localStorage;
    storage.getItem("sb-storage-check");
    return false;
  } catch {
    try {
      Object.defineProperty(target, "localStorage", { configurable: true, value: memoryStorage() });
      return true;
    } catch {
      return false;
    }
  }
}

guardLocalStorage();
